const input = $input.first().json;
const VERSION = '1.0';
const MARKER = 'alfa-mail-gateway-v1';
const MAX_BODY = 12000;
const safeId = (value, max = 200) => typeof value === 'string' && value.length <= max && /^[A-Za-z0-9.!#$%&'*+\/=?^_`{|}~@<>:;,.() \-[\]]+$/.test(value) ? value.trim() : '';
const correlationId = typeof input.correlationId === 'string' && /^[A-Za-z0-9._:-]{1,128}$/.test(input.correlationId) ? input.correlationId : crypto.randomUUID();
const testMode = input.testMode !== false;
const base = {contractVersion: VERSION, correlationId, testMode, operation: input.operation ?? ''};
const result = (ok, status, extra = {}) => [{json:{...base, ok, status, sendAuthorized:false, ...extra}}];
const fail = (code, message, extra = {}) => result(false, 'rejected', {error:{code,message}, ...extra});
const only = (object, keys) => object && typeof object === 'object' && !Array.isArray(object) && Object.keys(object).every((key) => keys.has(key));
if (!only(input, new Set(['contractVersion','testMode','operation','correlationId','message','draft','approval','sender']))) return fail('INVALID_REQUEST','Input contains unknown fields');
if (input.contractVersion !== undefined && input.contractVersion !== VERSION) return fail('UNSUPPORTED_CONTRACT','contractVersion must be 1.0');
const operation = input.operation;
if (!['normalizeIncoming','createDraft','authorizeSend'].includes(operation)) return fail('INVALID_OPERATION','operation must be normalizeIncoming, createDraft, or authorizeSend');
const cleanText = (value, max = MAX_BODY) => {
  const raw = typeof value === 'string' ? value : '';
  const clean = raw.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '').replace(/\r\n?/g, '\n').trim();
  return {value: clean.slice(0, max), truncated: clean.length > max};
};
const htmlToText = (value) => {
  const raw = typeof value === 'string' ? value.slice(0, 100000) : '';
  const stripped = raw.replace(/<(script|style|head|iframe|object|embed|form|svg|math)[^>]*>[\s\S]*?<\/\1\s*>/gi, ' ').replace(/<!--([\s\S]*?)-->/g, ' ').replace(/<\s*br\s*\/?\s*>/gi, '\n').replace(/<\/\s*(p|div|li|tr|h[1-6])\s*>/gi, '\n').replace(/<[^>]+>/g, ' ').replace(/&nbsp;|&#160;/gi, ' ').replace(/&amp;/gi, '&').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>').replace(/&quot;/gi, '"').replace(/&#39;|&apos;/gi, "'").replace(/&#(\d{1,6});/g, (_, n) => { const cp = Number(n); return cp > 31 && cp <= 0x10ffff ? String.fromCodePoint(cp) : ' '; }).replace(/javascript\s*:|data\s*:\s*text\/html/gi, '[blocked-uri]').replace(/[ \t]+/g, ' ').replace(/ *\n */g, '\n').replace(/\n{3,}/g, '\n\n').trim();
  return cleanText(stripped);
};
const mailbox = (value, maxCount) => {
  const source = Array.isArray(value) ? value : typeof value === 'string' ? value.split(',') : [];
  if (source.length > maxCount) return null;
  const normalized = [];
  for (const entry of source) {
    if (typeof entry !== 'string' || /[\r\n]/.test(entry)) return null;
    const match = entry.trim().match(/^(?:[^<>]{1,80}<)?([A-Z0-9.!#$%&'*+\/=?^_`{|}~-]+@[A-Z0-9.-]+\.[A-Z]{2,63})>?$/i);
    if (!match) return null;
    normalized.push(match[1].toLowerCase());
  }
  return [...new Set(normalized)];
};
const attachments = (value) => {
  if (value === undefined) return {ok:true, items:[], totalBytes:0};
  if (!Array.isArray(value) || value.length > 10) return {ok:false};
  let totalBytes = 0;
  const items = [];
  for (const item of value) {
    if (!only(item, new Set(['fileRef','fileName','mimeType','size']))) return {ok:false};
    if (typeof item.fileRef !== 'string' || !/^[A-Za-z0-9._:-]{3,128}$/.test(item.fileRef)) return {ok:false};
    if (typeof item.fileName !== 'string' || item.fileName.length < 1 || item.fileName.length > 160 || /[\r\n\/\\]/.test(item.fileName)) return {ok:false};
    if (typeof item.mimeType !== 'string' || !/^[a-z0-9.+-]{1,64}\/[a-z0-9.+-]{1,64}$/i.test(item.mimeType)) return {ok:false};
    if (!Number.isInteger(item.size) || item.size < 0 || item.size > 10 * 1024 * 1024) return {ok:false};
    totalBytes += item.size;
    if (totalBytes > 20 * 1024 * 1024) return {ok:false};
    items.push({fileRef:item.fileRef,fileName:item.fileName,mimeType:item.mimeType,size:item.size});
  }
  return {ok:true,items,totalBytes};
};
const normalizeDraft = (draft) => {
  if (!only(draft, new Set(['idempotencyKey','to','cc','bcc','subject','bodyText','inReplyTo','references','attachments','draftOnly','processingMarker']))) return {error:['INVALID_DRAFT','Draft contains unknown fields']};
  if (typeof draft.idempotencyKey !== 'string' || !/^[A-Za-z0-9._:-]{8,128}$/.test(draft.idempotencyKey)) return {error:['INVALID_IDEMPOTENCY_KEY','A safe idempotencyKey is required']};
  const to = mailbox(draft.to, 10); const cc = mailbox(draft.cc, 5); const bcc = mailbox(draft.bcc, 5);
  if (!to || to.length === 0 || !cc || !bcc) return {error:['INVALID_RECIPIENT','Recipient addresses are invalid or exceed limits']};
  if (typeof draft.subject !== 'string' || draft.subject.trim().length < 1 || draft.subject.length > 200 || /[\r\n]/.test(draft.subject)) return {error:['INVALID_SUBJECT','Subject must be 1..200 characters without line breaks']};
  const body = cleanText(draft.bodyText);
  if (!body.value) return {error:['INVALID_BODY','Plain-text body is required']};
  const refs = Array.isArray(draft.references) ? draft.references : draft.references ? [draft.references] : [];
  if (refs.length > 20 || refs.some((ref) => !safeId(ref))) return {error:['INVALID_THREAD','Thread identifiers are invalid']};
  if (draft.inReplyTo !== undefined && !safeId(draft.inReplyTo)) return {error:['INVALID_THREAD','inReplyTo is invalid']};
  if (draft.processingMarker !== undefined && draft.processingMarker !== MARKER) return {error:['INVALID_MARKER','Outgoing processingMarker must use the canonical marker']};
  const files = attachments(draft.attachments);
  if (!files.ok) return {error:['INVALID_ATTACHMENTS','Attachment metadata exceeds safety limits']};
  return {draft:{idempotencyKey:draft.idempotencyKey,to,cc,bcc,subject:draft.subject.trim(),bodyText:body.value,bodyTruncated:body.truncated,inReplyTo:draft.inReplyTo ?? null,references:refs,attachments:files.items,draftOnly:draft.draftOnly !== false,processingMarker:MARKER}};
};
if (operation === 'normalizeIncoming') {
  const message = input.message;
  if (!only(message, new Set(['messageId','inReplyTo','references','from','to','cc','subject','text','html','receivedAt','attachments','processingMarker']))) return fail('INVALID_MESSAGE','Message contains unknown fields');
  if (!safeId(message.messageId)) return fail('INVALID_MESSAGE_ID','A bounded messageId is required');
  if (message.processingMarker === MARKER) return fail('LOOP_DETECTED','Message was produced by this mail gateway');
  const from = mailbox(message.from, 1); const to = mailbox(message.to, 10); const cc = mailbox(message.cc, 5);
  if (!from || from.length !== 1 || !to || !cc) return fail('INVALID_ADDRESS','Message addresses are invalid or exceed limits');
  if (typeof message.subject !== 'string' || message.subject.length > 200 || /[\r\n]/.test(message.subject)) return fail('INVALID_SUBJECT','Subject is invalid');
  const receivedAt = new Date(message.receivedAt);
  if (Number.isNaN(receivedAt.getTime())) return fail('INVALID_TIME','receivedAt must be an ISO timestamp');
  const refs = Array.isArray(message.references) ? message.references : message.references ? [message.references] : [];
  if (refs.length > 20 || refs.some((ref) => !safeId(ref)) || (message.inReplyTo !== undefined && !safeId(message.inReplyTo))) return fail('INVALID_THREAD','Thread identifiers are invalid');
  const files = attachments(message.attachments);
  if (!files.ok) return fail('INVALID_ATTACHMENTS','Attachment metadata exceeds safety limits');
  const plain = cleanText(message.text); const html = htmlToText(message.html); const content = plain.value ? plain : html;
  if (!content.value) return fail('EMPTY_CONTENT','Message has no safe text content');
  const threadRef = message.inReplyTo || refs.at(-1) || message.messageId;
  return result(true,'normalized',{message:{messageId:message.messageId,inReplyTo:message.inReplyTo ?? null,references:refs,threadRef,from:from[0],to,cc,subject:message.subject.trim(),safeText:content.value,contentSource:plain.value?'text':'sanitized-html',contentTruncated:content.truncated,untrustedContent:true,receivedAt:receivedAt.toISOString(),attachments:files.items,totalAttachmentBytes:files.totalBytes,processingMarker:MARKER}});
}
const prepared = normalizeDraft(input.draft);
if (prepared.error) return fail(prepared.error[0],prepared.error[1]);
if (operation === 'createDraft') return result(true,'draft',{draft:prepared.draft});
const sender = input.sender;
if (!only(sender, new Set(['fromEmail','replyTo']))) return fail('INVALID_SENDER','Sender contains unknown fields',{draft:prepared.draft});
const from = mailbox(sender.fromEmail,1); const replyTo = sender.replyTo === undefined ? [] : mailbox(sender.replyTo,1);
if (!from || from.length !== 1 || !replyTo) return fail('INVALID_SENDER','Sender addresses are invalid',{draft:prepared.draft});
const approval = input.approval;
const approved = only(approval,new Set(['contractVersion','testMode','correlationId','ok','status','reason','allowAction','idempotencyKey','expiresAt','decision'])) && approval.contractVersion === VERSION && approval.ok === true && approval.status === 'approved' && approval.allowAction === true && approval.idempotencyKey === prepared.draft.idempotencyKey;
if (testMode) return result(true,'preview',{reason:'TEST_MODE',draft:prepared.draft});
if (prepared.draft.draftOnly) return result(true,'draft',{reason:'DRAFT_ONLY',draft:prepared.draft});
if (prepared.draft.attachments.length) return fail('ATTACHMENT_REVIEW_REQUIRED','SMTP attachments are disabled until a separate content-scan gate is implemented',{draft:prepared.draft});
if (!approved) return result(true,'denied',{reason:'EXPLICIT_APPROVAL_REQUIRED',draft:prepared.draft});
return [{json:{...base,ok:true,status:'authorized',sendAuthorized:true,draft:prepared.draft,smtp:{fromEmail:from[0],replyTo:replyTo[0] ?? ''}}}];

const current = $input.first().json;
if (current.sendAuthorized !== true) return [{json:current}];
const original = $('Called by Business Workflow').first().json;
const approval = original.approval;
const only = (object, keys) => object && typeof object === 'object' && !Array.isArray(object) && Object.keys(object).every((key) => keys.has(key));
const expiry = new Date(approval?.expiresAt);
const exact = only(approval,new Set(['contractVersion','testMode','correlationId','ok','status','reason','allowAction','idempotencyKey','expiresAt','decision'])) && approval.contractVersion === '1.0' && approval.ok === true && approval.status === 'approved' && approval.allowAction === true && approval.idempotencyKey === current.draft?.idempotencyKey && !Number.isNaN(expiry.getTime()) && expiry > new Date() && only(approval.decision,new Set(['state','approverRef'])) && approval.decision.state === 'approved' && typeof approval.decision.approverRef === 'string' && /^[A-Za-z0-9._:-]{3,128}$/.test(approval.decision.approverRef);
